public int[] twoSum(int[] nums, int target) {
    Map<Integer, Integer> seen = new HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int need = target - nums[i];
        if (seen.containsKey(need))
            return new int[]{ seen.get(need), i };
        seen.put(nums[i], i);
    }
    return new int[]{}; // no valid pair
}

public int maxProfit(int[] prices) {
    int minPrice = Integer.MAX_VALUE;
    int maxProfit = 0;
    for (int p : prices) {
        minPrice = Math.min(minPrice, p);     // cheapest buy so far
        maxProfit = Math.max(maxProfit, p - minPrice);
    }
    return maxProfit;
}

public int[] productExceptSelf(int[] nums) {
    int n = nums.length;
    int[] res = new int[n];
    res[0] = 1;
    for (int i = 1; i < n; i++)          // prefix product
        res[i] = res[i - 1] * nums[i - 1];
    int suffix = 1;
    for (int i = n - 1; i >= 0; i--) {   // multiply suffix product
        res[i] *= suffix;
        suffix *= nums[i];
    }
    return res;
}

public int maxSubArray(int[] nums) {
    int curr = nums[0];   // best sum ending at current index
    int best = nums[0];
    for (int i = 1; i < nums.length; i++) {
        curr = Math.max(nums[i], curr + nums[i]); // extend or restart
        best = Math.max(best, curr);
    }
    return best;
}

public int[][] merge(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> a[0] - b[0]);   // sort by start
    List<int[]> out = new ArrayList<>();
    int[] cur = intervals[0];
    for (int i = 1; i < intervals.length; i++) {
        if (intervals[i][0] <= cur[1])               // overlap
            cur[1] = Math.max(cur[1], intervals[i][1]);
        else {
            out.add(cur);
            cur = intervals[i];
        }
    }
    out.add(cur);
    return out.toArray(new int[out.size()][]);
}

public int maxArea(int[] height) {
    int l = 0, r = height.length - 1, best = 0;
    while (l < r) {
        int area = Math.min(height[l], height[r]) * (r - l);
        best = Math.max(best, area);
        if (height[l] < height[r]) l++;  // move the shorter wall inward
        else r--;
    }
    return best;
}

public List<List<Integer>> threeSum(int[] nums) {
    Arrays.sort(nums);
    List<List<Integer>> res = new ArrayList<>();
    for (int i = 0; i < nums.length - 2; i++) {
        if (i > 0 && nums[i] == nums[i - 1]) continue;   // skip dup anchor
        int l = i + 1, r = nums.length - 1;
        while (l < r) {
            int sum = nums[i] + nums[l] + nums[r];
            if (sum == 0) {
                res.add(Arrays.asList(nums[i], nums[l], nums[r]));
                while (l < r && nums[l] == nums[l + 1]) l++;
                while (l < r && nums[r] == nums[r - 1]) r--;
                l++; r--;
            } else if (sum < 0) l++;
            else r--;
        }
    }
    return res;
}

public int trap(int[] height) {
    int l = 0, r = height.length - 1;
    int leftMax = 0, rightMax = 0, water = 0;
    while (l < r) {
        if (height[l] < height[r]) {
            leftMax = Math.max(leftMax, height[l]);
            water += leftMax - height[l];   // bounded by left wall
            l++;
        } else {
            rightMax = Math.max(rightMax, height[r]);
            water += rightMax - height[r];  // bounded by right wall
            r--;
        }
    }
    return water;
}

public int lengthOfLongestSubstring(String s) {
    Map<Character, Integer> last = new HashMap<>();
    int start = 0, best = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (last.containsKey(c) && last.get(c) >= start)
            start = last.get(c) + 1;     // shrink window past last dup
        last.put(c, i);
        best = Math.max(best, i - start + 1);
    }
    return best;
}

public boolean isValid(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (c == '(') stack.push(')');
        else if (c == '[') stack.push(']');
        else if (c == '{') stack.push('}');
        else if (stack.isEmpty() || stack.pop() != c)
            return false;   // mismatch or nothing to close
    }
    return stack.isEmpty();
}

public List<List<String>> groupAnagrams(String[] strs) {
    Map<String, List<String>> groups = new HashMap<>();
    for (String s : strs) {
        char[] ch = s.toCharArray();
        Arrays.sort(ch);                 // sorted form is the key
        String key = new String(ch);
        groups.computeIfAbsent(key, k -> new ArrayList<>()).add(s);
    }
    return new ArrayList<>(groups.values());
}

public String longestPalindrome(String s) {
    if (s.length() < 2) return s;
    int start = 0, len = 1;
    for (int i = 0; i < s.length(); i++) {
        int odd = expand(s, i, i);       // centre on a char
        int even = expand(s, i, i + 1);  // centre between chars
        int max = Math.max(odd, even);
        if (max > len) {
            len = max;
            start = i - (max - 1) / 2;
        }
    }
    return s.substring(start, start + len);
}
private int expand(String s, int l, int r) {
    while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
        l--; r++;
    }
    return r - l - 1;
}

public ListNode reverseList(ListNode head) {
    ListNode prev = null, curr = head;
    while (curr != null) {
        ListNode next = curr.next;  // save next
        curr.next = prev;           // reverse pointer
        prev = curr;                // advance prev
        curr = next;                // advance curr
    }
    return prev;
}

public boolean hasCycle(ListNode head) {
    ListNode slow = head, fast = head;   // Floyd's tortoise & hare
    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;
        if (slow == fast) return true;   // pointers met -> cycle
    }
    return false;
}

public ListNode mergeTwoLists(ListNode a, ListNode b) {
    ListNode dummy = new ListNode(0), tail = dummy;
    while (a != null && b != null) {
        if (a.val <= b.val) { tail.next = a; a = a.next; }
        else                { tail.next = b; b = b.next; }
        tail = tail.next;
    }
    tail.next = (a != null) ? a : b;   // attach remaining nodes
    return dummy.next;
}

public int maxDepth(TreeNode root) {
    if (root == null) return 0;
    int left = maxDepth(root.left);
    int right = maxDepth(root.right);
    return 1 + Math.max(left, right);   // 1 for current node
}

public List<List<Integer>> levelOrder(TreeNode root) {
    List<List<Integer>> res = new ArrayList<>();
    if (root == null) return res;
    Queue<TreeNode> q = new LinkedList<>();
    q.offer(root);
    while (!q.isEmpty()) {
        int size = q.size();             // nodes in this level
        List<Integer> level = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            TreeNode node = q.poll();
            level.add(node.val);
            if (node.left != null) q.offer(node.left);
            if (node.right != null) q.offer(node.right);
        }
        res.add(level);
    }
    return res;
}

public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
    while (root != null) {
        if (p.val < root.val && q.val < root.val)
            root = root.left;       // both smaller -> go left
        else if (p.val > root.val && q.val > root.val)
            root = root.right;      // both larger -> go right
        else
            return root;            // split point -> LCA
    }
    return null;
}

private int diameter = 0;
public int diameterOfBinaryTree(TreeNode root) {
    depth(root);
    return diameter;
}
private int depth(TreeNode node) {
    if (node == null) return 0;
    int left = depth(node.left);
    int right = depth(node.right);
    diameter = Math.max(diameter, left + right); // path through node
    return 1 + Math.max(left, right);
}

public boolean isValidBST(TreeNode root) {
    return valid(root, Long.MIN_VALUE, Long.MAX_VALUE);
}
private boolean valid(TreeNode node, long min, long max) {
    if (node == null) return true;
    if (node.val <= min || node.val >= max) return false;
    return valid(node.left, min, node.val)        // tighten upper bound
        && valid(node.right, node.val, max);      // tighten lower bound
}

public int numIslands(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++)
        for (int j = 0; j < grid[0].length; j++)
            if (grid[i][j] == '1') {
                sink(grid, i, j);   // flood-fill this island
                count++;
            }
    return count;
}
private void sink(char[][] g, int i, int j) {
    if (i < 0 || j < 0 || i >= g.length || j >= g[0].length || g[i][j] != '1')
        return;
    g[i][j] = '0';                  // mark visited
    sink(g, i + 1, j);
    sink(g, i - 1, j);
    sink(g, i, j + 1);
    sink(g, i, j - 1);
}

public int search(int[] nums, int target) {
    int l = 0, r = nums.length - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (nums[mid] == target) return mid;
        if (nums[l] <= nums[mid]) {              // left half sorted
            if (nums[l] <= target && target < nums[mid]) r = mid - 1;
            else l = mid + 1;
        } else {                                 // right half sorted
            if (nums[mid] < target && target <= nums[r]) l = mid + 1;
            else r = mid - 1;
        }
    }
    return -1;
}

public int climbStairs(int n) {
    if (n <= 2) return n;
    int prev = 1, curr = 2;          // ways to reach step 1 and 2
    for (int i = 3; i <= n; i++) {
        int next = prev + curr;      // Fibonacci recurrence
        prev = curr;
        curr = next;
    }
    return curr;
}

public int rob(int[] nums) {
    int prev = 0, curr = 0;   // best loot up to previous two houses
    for (int n : nums) {
        int take = prev + n;          // rob this house
        int skip = curr;              // skip this house
        prev = curr;
        curr = Math.max(take, skip);
    }
    return curr;
}

public int longestCommonSubsequence(String a, String b) {
    int m = a.length(), n = b.length();
    int[][] dp = new int[m + 1][n + 1];
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++) {
            if (a.charAt(i - 1) == b.charAt(j - 1))
                dp[i][j] = dp[i - 1][j - 1] + 1;       // chars match
            else
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    return dp[m][n];
}

public int lengthOfLIS(int[] nums) {
    List<Integer> tails = new ArrayList<>();   // patience sorting
    for (int n : nums) {
        int i = Collections.binarySearch(tails, n);
        if (i < 0) i = -(i + 1);               // insertion point
        if (i == tails.size()) tails.add(n);
        else tails.set(i, n);                  // replace to keep tails small
    }
    return tails.size();
}

public List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    backtrack(nums, 0, new ArrayList<>(), res);
    return res;
}
private void backtrack(int[] nums, int start, List<Integer> path, List<List<Integer>> res) {
    res.add(new ArrayList<>(path));     // every node is a valid subset
    for (int i = start; i < nums.length; i++) {
        path.add(nums[i]);              // choose
        backtrack(nums, i + 1, path, res);
        path.remove(path.size() - 1);   // un-choose
    }
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    backtrack(nums, new ArrayList<>(), new boolean[nums.length], res);
    return res;
}
private void backtrack(int[] nums, List<Integer> path, boolean[] used, List<List<Integer>> res) {
    if (path.size() == nums.length) {
        res.add(new ArrayList<>(path));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;          // skip already-used element
        used[i] = true;
        path.add(nums[i]);
        backtrack(nums, path, used, res);
        path.remove(path.size() - 1);   // backtrack
        used[i] = false;
    }
}

public List<List<Integer>> combinationSum(int[] candidates, int target) {
    List<List<Integer>> res = new ArrayList<>();
    backtrack(candidates, target, 0, new ArrayList<>(), res);
    return res;
}
private void backtrack(int[] c, int remain, int start, List<Integer> path, List<List<Integer>> res) {
    if (remain == 0) { res.add(new ArrayList<>(path)); return; }
    if (remain < 0) return;             // overshot the target
    for (int i = start; i < c.length; i++) {
        path.add(c[i]);
        backtrack(c, remain - c[i], i, path, res); // i (not i+1) -> reuse allowed
        path.remove(path.size() - 1);
    }
}
